#include "sim/npc.h"
#include "core/ecs/view.h"
#include <cstdint>
#include <stdexcept>
namespace nuc::sim {
ecs::Entity NpcSystem::spawn(ecs::World& world,int x,int y,int z){auto e=world.create();world.emplace<NpcTag>(e);world.emplace<NpcGoal>(e);world.emplace<NpcPosition>(e,NpcPosition{x,y,z});world.emplace<NpcInventory>(e);world.emplace<NpcLod>(e);return e;}
void NpcSystem::tick(ecs::World& world){ecs::view<NpcTag,NpcGoal,NpcPosition,NpcInventory>(world).each([](ecs::Entity,NpcTag&,NpcGoal& goal,NpcPosition& pos,NpcInventory& inv){switch(goal.state){case NpcState::Idle:if(goal.completed)return;if(pos.x==goal.target_x&&pos.y==goal.target_y&&pos.z==goal.target_z){goal.state=NpcState::Work;goal.remaining_ticks=goal.work_ticks;}else goal.state=NpcState::GoTo;break;case NpcState::GoTo:if(pos.x!=goal.target_x)pos.x+=pos.x<goal.target_x?1:-1;else if(pos.y!=goal.target_y)pos.y+=pos.y<goal.target_y?1:-1;else if(pos.z!=goal.target_z)pos.z+=pos.z<goal.target_z?1:-1;if(pos.x==goal.target_x&&pos.y==goal.target_y&&pos.z==goal.target_z){goal.state=NpcState::Work;goal.remaining_ticks=goal.work_ticks;}break;case NpcState::Work:if(goal.remaining_ticks>0)--goal.remaining_ticks;if(goal.remaining_ticks==0&&inv.inventory.can_insert({goal.work_item,goal.work_count,64})&&inv.inventory.insert({goal.work_item,goal.work_count,64})==goal.work_count){goal.completed=true;goal.state=NpcState::Eat;}break;case NpcState::Eat:goal.state=NpcState::Sleep;break;case NpcState::Sleep:goal.state=NpcState::Idle;break;}});}
void NpcSystem::update_tiers(ecs::World& world,int px,int py,int pz,int radius){if(radius<=0)throw std::invalid_argument("NPC tier radius must be positive");const std::int64_t r=radius,far=4*r;const auto near2=r*r,far2=far*far;ecs::view<NpcTag,NpcPosition,NpcLod>(world).each([&](ecs::Entity,NpcTag&,NpcPosition& p,NpcLod& lod){const std::int64_t dx=static_cast<std::int64_t>(p.x)-px,dy=static_cast<std::int64_t>(p.y)-py,dz=static_cast<std::int64_t>(p.z)-pz;const auto d2=dx*dx+dy*dy+dz*dz;lod.tier=d2<=near2?NpcTier::Tier0:(d2<=far2?NpcTier::Tier1:NpcTier::Tier2);});}
void CivilizationSystem::tick(std::vector<Civilization>& civs,unsigned rate){if(rate==0)throw std::invalid_argument("civilization tick rate must be positive");for(auto& c:civs){if(++c.ticks_into_second<rate)continue;c.ticks_into_second=0;for(const auto& [item,amount]:c.production_per_second)c.resources[item]+=amount;}}
}
